32	
33	  const memoUpdatedCallback = useCallback(() => {
34	    // Invalidate user stats to trigger refetch
35	    queryClient.invalidateQueries({ queryKey: userKeys.stats() });
36	  }, [queryClient]);
37	
38	  const updateMemoContent = useCallback(
39	    async (nextContent: string, context: string) => {
40	      if (nextContent === memo.content) {
41	        return;
42	      }
43	
44	      try {
45	        await updateMemo({
46	          update: {
47	            name: memo.name,
48	            content: nextContent,
49	          },
50	          updateMask: ["content", "update_time"],
51	        });
52	        toast.success(t("memo.task-actions.updated"));
53	      } catch (error: unknown) {
54	        handleError(error, toast.error, {
55	          context,
56	          fallbackMessage: "An error occurred",
57	        });
58	      }
59	    },
60	    [memo.content, memo.name, t, updateMemo],
61	  );
62	
63	  const handleTogglePinMemoBtnClick = useCallback(async () => {
