131	  const handleDeleteMemoClick = useCallback(() => {
132	    setDeleteDialogOpen(true);
133	  }, [setDeleteDialogOpen]);
134	
135	  const confirmDeleteMemo = useCallback(async () => {
136	    try {
137	      await deleteMemo(memo.name);
