1	import { useQueryClient } from "@tanstack/react-query";
2	import { useMemo } from "react";
3	import { memoServiceClient } from "@/connect";
4	import useCurrentUser from "@/hooks/useCurrentUser";
5	import { memoKeys } from "@/hooks/useMemoQueries";
6	import { useUsersByNames } from "@/hooks/useUserQueries";
7	import type { Memo, Reaction } from "@/types/proto/api/v1/memo_service_pb";
8	import type { User } from "@/types/proto/api/v1/user_service_pb";
9	
10	export type ReactionGroup = Map<string, User[]>;
11	
12	export const useReactionGroups = (reactions: Reaction[]): ReactionGroup => {
13	  const creatorNames = useMemo(() => reactions.map((r) => r.creator), [reactions]);
14	  const { data: userMap } = useUsersByNames(creatorNames);
15	
16	  return useMemo(() => {
17	    const reactionGroup = new Map<string, User[]>();
18	    for (const reaction of reactions) {
19	      const user = userMap?.get(reaction.creator);
20	      if (!user) continue;
21	
22	      const users = reactionGroup.get(reaction.reactionType) || [];
23	      users.push(user);
24	      reactionGroup.set(reaction.reactionType, users);
25	    }
26	    return reactionGroup;
27	  }, [reactions, userMap]);
28	};
29	
30	interface UseReactionActionsOptions {
31	  memo: Memo;
32	  onComplete?: () => void;
33	}
34	
35	export const useReactionActions = ({ memo, onComplete }: UseReactionActionsOptions) => {
36	  const currentUser = useCurrentUser();
37	  const queryClient = useQueryClient();
38	
39	  const hasReacted = (reactionType: string) => {
40	    return memo.reactions.some((r) => r.reactionType === reactionType && r.creator === currentUser?.name);
41	  };
42	
43	  const handleReactionClick = async (reactionType: string) => {
44	    if (!currentUser) return;
45	
46	    try {
47	      if (hasReacted(reactionType)) {
48	        const reactions = memo.reactions.filter(
49	          (reaction) => reaction.reactionType === reactionType && reaction.creator === currentUser.name,
50	        );
51	        await Promise.all(reactions.map((reaction) => memoServiceClient.deleteMemoReaction({ name: reaction.name })));
52	      } else {
53	        await memoServiceClient.upsertMemoReaction({
54	          name: memo.name,
55	          reaction: { contentId: memo.name, reactionType },
56	        });
57	      }
58	      // Refetch the memo to get updated reactions and invalidate cache
59	      const updatedMemo = await memoServiceClient.getMemo({ name: memo.name });
60	      queryClient.setQueryData(memoKeys.detail(memo.name), updatedMemo);
61	      queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
62	      // If this memo is a comment, refresh the parent's comments list so the comment's reactions update in the UI
63	      if (memo.parent) {
64	        queryClient.invalidateQueries({ queryKey: memoKeys.comments(memo.parent) });
65	      }
66	    } catch {
67	      // skip error
68	    }
69	    onComplete?.();
70	  };
71	
72	  return { hasReacted, handleReactionClick };
73	};
74	
75	export const formatReactionTooltip = (users: User[], reactionType: string): string => {
76	  if (users.length === 0) return "";
77	  const formatUserName = (user: User) => user.displayName || user.username;
78	  if (users.length < 5) {
79	    return `${users.map(formatUserName).join(", ")} reacted with ${reactionType.toLowerCase()}`;
80	  }
81	  return `${users.slice(0, 4).map(formatUserName).join(", ")} and ${users.length - 4} more reacted with ${reactionType.toLowerCase()}`;
82	};
